1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/base64"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"os"
11		"path/filepath"
12		"reflect"
13		"sort"
14	)
15	
16	// ExportResult summarizes a successful snapshot export.
17	type ExportResult struct {
18		Name    string
19		Entries int
20		Objects int
21	}
22	
23	// ImportResult summarizes a successful snapshot import.
24	type ImportResult struct {
25		Name       string
26		Entries    int
27		NewObjects int
28	}
29	
30	// ExportSnapshot writes the named snapshot, together with the content objects
31	// it needs, to output as a portable package.
32	//
33	// Without a base the package is complete: every referenced object is carried,
34	// and a digest shared by several entries is carried once. With base set to the
35	// name of another snapshot in the same repository, the package still records
36	// the target's complete mapping but only carries objects the base does not
37	// reference; an importer can only apply it on top of an identical base.
38	//
39	// Every object the target references is re-read and checked for recorded size
40	// and SHA-256, including objects omitted from a delta, so a corrupt snapshot
41	// record or a missing/damaged object never produces a successful package. The
42	// package is assembled in memory and written to a temporary file beside the
43	// destination before an atomic rename: a failed export never creates or
44	// alters the output file.
45	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
46		if err := validateName(name); err != nil {
47			return ExportResult{}, err
48		}
49		if base != "" {
50			if err := validateName(base); err != nil {
51				return ExportResult{}, err
52			}
53		}
54		if output == "" {
55			return ExportResult{}, errors.New("output is required")
56		}
57		var result ExportResult
58		err := s.withLock(true, func() error {
59			if err := s.initLocked(); err != nil {
60				return err
61			}
62			target, err := s.loadSnapshotRecord(name)
63			if err != nil {
64				return err
65			}
66			pkg := &Package{
67				Format:   packageFormat,
68				Version:  packageVersion,
69				Snapshot: target,
70				Objects:  []PackageObject{},
71			}
72			var baseSnap Snapshot
73			if base != "" {
74				var err error
75				baseSnap, err = s.loadSnapshotRecord(base)
76				if err != nil {
77					return fmt.Errorf("cannot use base snapshot: %w", err)
78				}
79				pkg.Base = &baseSnap
80			}
81	
82			// Verify every object the target references, reading each once. This
83			// includes objects the delta omits because the base references them:
84			// certifying the delta requires those to be intact too. Only objects
85			// the base does not reference are carried. Digests are processed in
86			// sorted order so the package layout and any failure message are
87			// deterministic.
88			carry := digestsReferenced(target.Entries)
89			if base != "" {
90				for digest := range digestsReferenced(baseSnap.Entries) {
91					delete(carry, digest)
92				}
93			}
94			for _, digest := range sortedDigests(target.Entries) {
95				content, size, err := s.readVerifiedObject(digest, target.Entries)
96				if err != nil {
97					return fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
98				}
99				if _, included := carry[digest]; !included {
100					continue
101				}
102				pkg.Objects = append(pkg.Objects, PackageObject{
103					Digest: digest,
104					Size:   size,
105					Data:   base64.StdEncoding.EncodeToString(content),
106				})
107			}
108	
109			data, err := marshalPackage(pkg)
110			if err != nil {
111				return err
112			}
113			if err := writeFileAtomic(output, data, ".package-*"); err != nil {
114				return err
115			}
116			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: len(pkg.Objects)}
117			return nil
118		})
119		if err != nil {
120			return ExportResult{}, err
121		}
122		return result, nil
123	}
124	
125	// ImportSnapshot imports a snapshot package produced by ExportSnapshot into an
126	// initialized repository.
127	//
128	// Import only adds the package's snapshot and any missing content objects; it
129	// never changes the current name mapping or any existing snapshot or object.
130	// A delta package is accepted only when the destination already contains a
131	// snapshot with the base name and byte-identical entry metadata, and every
132	// object the delta omits is present and intact. Healthy objects already in the
133	// destination are reused; re-importing a package whose snapshot is already
134	// present with identical metadata succeeds without creating a second copy. A
135	// same-named snapshot with different metadata is refused.
136	//
137	// All validation and reuse happens before anything is written. New objects
138	// land as complete files via temp-file-and-rename, and the snapshot record is
139	// renamed into place only after every object the mapping references has been
140	// verified, so a crash or write failure leaves at most unreferenced complete
141	// objects that a later gc removes and a retry succeeds; a partially imported
142	// snapshot can never be observed.
143	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
144		if file == "" {
145			return ImportResult{}, errors.New("file is required")
146		}
147		data, err := os.ReadFile(file)
148		if err != nil {
149			return ImportResult{}, err
150		}
151		pkg, err := decodePackage(data)
152		if err != nil {
153			return ImportResult{}, err
154		}
155		// Import targets an initialized repository; it never creates one the way
156		// mutating artifact commands do.
157		rootInfo, err := os.Stat(s.root)
158		switch {
159		case errors.Is(err, os.ErrNotExist):
160			return ImportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
161		case err != nil:
162			return ImportResult{}, err
163		case !rootInfo.IsDir():
164			return ImportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
165		}
166		var result ImportResult
167		err = s.withLock(true, func() error {
168			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
169				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
170			} else if err != nil {
171				return err
172			}
173			if err := rejectLinkedDirs(s.root); err != nil {
174				return err
175			}
176	
177			// A delta must sit on an exactly matching base: same snapshot name and
178			// identical entry metadata. A merely same-named snapshot, or objects
179			// that happen to share digests, is not a base.
180			if pkg.Base != nil {
181				existing, err := s.loadSnapshotRecord(pkg.Base.Name)
182				if err != nil {
183					return fmt.Errorf("delta base snapshot %q is unavailable: %w", pkg.Base.Name, err)
184				}
185				if !snapshotsEqual(existing, *pkg.Base) {
186					return fmt.Errorf("delta base snapshot %q does not match the package base", pkg.Base.Name)
187				}
188				if err := s.verifyReferencedObjects(pkg.Base.Name, existing.Entries); err != nil {
189					return fmt.Errorf("delta base snapshot %q is not fully present: %w", pkg.Base.Name, err)
190				}
191			}
192	
193			// A same-named destination snapshot is either identical metadata or a
194			// collision. A collision is refused before anything is staged.
195			targetPath := s.snapshotPath(pkg.Snapshot.Name)
196			identicalSnapshot := false
197			if existing, statErr := os.Lstat(targetPath); statErr == nil {
198				if existing.Mode()&os.ModeSymlink != 0 {
199					return fmt.Errorf("snapshot path %q is a symbolic link", targetPath)
200				}
201				current, err := s.loadSnapshotRecord(pkg.Snapshot.Name)
202				if err != nil {
203					return fmt.Errorf("snapshot %q already exists and is unusable: %w", pkg.Snapshot.Name, err)
204				}
205				if !snapshotsEqual(current, pkg.Snapshot) {
206					return fmt.Errorf("snapshot %q already exists with different metadata; refusing to overwrite", pkg.Snapshot.Name)
207				}
208				identicalSnapshot = true
209				// Fast path: everything the published snapshot needs is already
210				// present and healthy, so the import is a no-op.
211				if s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries) == nil {
212					result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: 0}
213					return nil
214				}
215				// Otherwise fall through: a carried object that is merely missing
216				// can be staged to complete an earlier interrupted import, while a
217				// damaged existing object still aborts below.
218			} else if !errors.Is(statErr, os.ErrNotExist) {
219				return statErr
220			}
221	
222			objects, err := pkg.materialize()
223			if err != nil {
224				return err
225			}
226	
227			// Phase 1, no writes: classify every carried object. Existing files
228			// must be healthy and are reused; a damaged one aborts the import and
229			// is reported by digest.
230			toAdd := make([]objectContent, 0, len(objects))
231			for _, obj := range objects {
232				path := s.objectPath(obj.digest)
233				info, err := os.Lstat(path)
234				switch {
235				case err == nil:
236					if info.Mode()&os.ModeSymlink != 0 {
237						return fmt.Errorf("object %s: object path is a symbolic link", obj.digest)
238					}
239					if !info.Mode().IsRegular() {
240						return fmt.Errorf("object %s: object path is not a regular file", obj.digest)
241					}
242					if _, _, err := s.readVerifiedObject(obj.digest, pkg.Snapshot.Entries); err != nil {
243						return fmt.Errorf("object %s already present but damaged: %w", obj.digest, err)
244					}
245				case errors.Is(err, os.ErrNotExist):
246					toAdd = append(toAdd, obj)
247				default:
248					return err
249				}
250			}
251	
252			// Phase 2: stage missing objects as complete, content-addressed files.
253			// A failure here leaves only unreferenced complete objects behind; a
254			// retry reuses them and finishes the import.
255			for _, obj := range toAdd {
256				if err := s.stageObject(obj.digest, obj.content); err != nil {
257					return err
258				}
259			}
260	
261			// Phase 3: the published mapping must be fully restorable. This covers
262			// reused objects, newly staged ones, and everything omitted by a delta.
263			if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
264				return err
265			}
266	
267			// Phase 4: publish the snapshot record last (unless an identical one is
268			// already published). This rename is the commit point; before it a new
269			// imported snapshot simply does not exist.
270			if !identicalSnapshot {
271				if err := s.saveSnapshot(targetPath, pkg.Snapshot); err != nil {
272					return err
273				}
274			}
275			result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: len(toAdd)}
276			return nil
277		})
278		if err != nil {
279			return ImportResult{}, err
280		}
281		return result, nil
282	}
283	
284	// loadSnapshotRecord reads and fully validates one stored snapshot: it must
285	// parse, carry a non-null entries mapping, record the same name it is filed
286	// under, and contain only valid entry records.
287	func (s *Store) loadSnapshotRecord(name string) (Snapshot, error) {
288		path := s.snapshotPath(name)
289		info, err := os.Lstat(path)
290		if errors.Is(err, os.ErrNotExist) {
291			return Snapshot{}, fmt.Errorf("snapshot %q not found", name)
292		}
293		if err != nil {
294			return Snapshot{}, err
295		}
296		if info.Mode()&os.ModeSymlink != 0 {
297			return Snapshot{}, fmt.Errorf("snapshot %q is a symbolic link", name)
298		}
299		if !info.Mode().IsRegular() {
300			return Snapshot{}, fmt.Errorf("snapshot %q is not a regular file", name)
301		}
302		data, err := os.ReadFile(path)
303		if err != nil {
304			return Snapshot{}, err
305		}
306		var snap Snapshot
307		if err := json.Unmarshal(data, &snap); err != nil {
308			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
309		}
310		if snap.Entries == nil {
311			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: missing entries mapping", name)
312		}
313		if snap.Name != name {
314			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: recorded name %q does not match its location", name, snap.Name)
315		}
316		for key, entry := range snap.Entries {
317			if err := validateEntryRecord(key, entry); err != nil {
318				return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
319			}
320		}
321		return snap, nil
322	}
323	
324	// verifyReferencedObjects checks each distinct referenced digest once against
325	// the stored object's size and SHA-256.
326	func (s *Store) verifyReferencedObjects(snapshotName string, entries map[string]Entry) error {
327		for _, digest := range sortedDigests(entries) {
328			if _, _, err := s.readVerifiedObject(digest, entries); err != nil {
329				return fmt.Errorf("object %s needed by snapshot %q: %w", digest, snapshotName, err)
330			}
331		}
332		return nil
333	}
334	
335	// readVerifiedObject reads a content object and returns its bytes, confirming
336	// its SHA-256 digest and the size recorded for it in the given entries.
337	func (s *Store) readVerifiedObject(digest string, entries map[string]Entry) ([]byte, int64, error) {
338		path := s.objectPath(digest)
339		info, err := os.Lstat(path)
340		if err != nil {
341			return nil, 0, err
342		}
343		if info.Mode()&os.ModeSymlink != 0 {
344			return nil, 0, errors.New("object path is a symbolic link")
345		}
346		if !info.Mode().IsRegular() {
347			return nil, 0, errors.New("object path is not a regular file")
348		}
349		content, err := os.ReadFile(path)
350		if err != nil {
351			return nil, 0, err
352		}
353		sum := sha256.Sum256(content)
354		if actual := hex.EncodeToString(sum[:]); actual != digest {
355			return nil, 0, fmt.Errorf("content checksum is %s", actual)
356		}
357		// Every entry referencing this digest must agree on the size; a content
358		// hash fixes the byte count, so a disagreement is a corrupt record.
359		for _, entry := range entries {
360			if entry.Digest == digest && int64(len(content)) != entry.Size {
361				return nil, 0, fmt.Errorf("content is %d bytes, record for %q says %d", len(content), entry.Name, entry.Size)
362			}
363		}
364		return content, int64(len(content)), nil
365	}
366	
367	// stageObject writes one missing object to a temp file and renames it into
368	// place. The content digest was verified when the package was decoded, so the
369	// final file is complete before it ever appears under its digest name.
370	func (s *Store) stageObject(digest string, content []byte) error {
371		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".import-*")
372		if err != nil {
373			return err
374		}
375		tmpName := tmp.Name()
376		defer os.Remove(tmpName)
377		if _, err := tmp.Write(content); err != nil {
378			tmp.Close()
379			return fmt.Errorf("object %s: %w", digest, err)
380		}
381		if err := tmp.Close(); err != nil {
382			return fmt.Errorf("object %s: %w", digest, err)
383		}
384		if err := os.Rename(tmpName, s.objectPath(digest)); err != nil {
385			return fmt.Errorf("object %s: %w", digest, err)
386		}
387		return nil
388	}
389	
390	// rejectLinkedDirs makes sure an import can never stage files outside the
391	// repository through a replaced objects or snapshots directory.
392	func rejectLinkedDirs(root string) error {
393		for _, dir := range []string{filepath.Join(root, "objects"), filepath.Join(root, "snapshots")} {
394			if err := ensureRealDir(dir); err != nil {
395				return err
396			}
397		}
398		return nil
399	}
400	
401	// writeFileAtomic writes data to a temporary file in the destination's
402	// directory and renames it over dest only after a complete flush. An existing
403	// destination is left untouched on any earlier failure.
404	func writeFileAtomic(dest string, data []byte, pattern string) error {
405		dir := filepath.Dir(dest)
406		if info, err := os.Lstat(dir); err != nil {
407			return err
408		} else if info.Mode()&os.ModeSymlink != 0 {
409			return fmt.Errorf("output directory %q is a symbolic link", dir)
410		}
411		tmp, err := os.CreateTemp(dir, pattern)
412		if err != nil {
413			return err
414		}
415		tmpName := tmp.Name()
416		defer os.Remove(tmpName)
417		if _, err := tmp.Write(data); err != nil {
418			tmp.Close()
419			return err
420		}
421		if err := tmp.Close(); err != nil {
422			return err
423		}
424		return os.Rename(tmpName, dest)
425	}
426	
427	// snapshotsEqual reports whether two snapshot records carry the same snapshot
428	// name and identical metadata for every entry.
429	func snapshotsEqual(a, b Snapshot) bool {
430		return reflect.DeepEqual(a.Entries, b.Entries) && a.Name == b.Name
431	}
432	
433	func sortedDigests(entries map[string]Entry) []string {
434		seen := map[string]struct{}{}
435		for _, entry := range entries {
436			seen[entry.Digest] = struct{}{}
437		}
438		out := make([]string, 0, len(seen))
439		for digest := range seen {
440			out = append(out, digest)
441		}
442		sort.Strings(out)
443		return out
444	}
