	outDir := filepath.Dir(outputAbs)
	// The parent must exist and be a directory (symlinks are followed here;
	// a symlinked parent that redirects the destination into the repository is
	// caught by the resolved containment check below).
	parentInfo, err := os.Stat(outDir)
	if err != nil {
		return "", "", fmt.Errorf("%w: output directory %q: %v", ErrOutputUnavailable, outDir, err)
	}
	if !parentInfo.IsDir() {
		return "", "", fmt.Errorf("%w: output directory %q is not a directory", ErrOutputUnavailable, outDir)
	}

	repoReal, err := filepath.EvalSymlinks(rootAbs)
	if err != nil {
		return "", "", fmt.Errorf("%w: cannot resolve repository %q: %v", ErrOutputUnavailable, s.root, err)
	}
	// Resolve every existing component of the output path. A symlink in a
	// parent directory must not let a destination that looks outside the
	// repository land inside it.
	outReal, err := resolveExisting(outputAbs)
	if err != nil {
		return "", "", fmt.Errorf("%w: %v", ErrOutputUnavailable, err)
	}
	if withinPath(outReal, repoReal) || withinPath(outputAbs, rootAbs) {
		return "", "", fmt.Errorf("%w: %s lies within the repository %q", ErrOutputUnavailable, output, s.root)
	}

	// CreateTemp insists on an existing real directory; resolve the temp
	// file's home the same way so it is physically next to the destination.
	dirReal, err := filepath.EvalSymlinks(outDir)
	if err != nil {
		return "", "", fmt.Errorf("%w: output directory %q: %v", ErrOutputUnavailable, outDir, err)
	}

	if info, lerr := os.Lstat(outputAbs); lerr == nil {
		if info.Mode()&os.ModeSymlink != 0 {
			return "", "", fmt.Errorf("%w: %s is a symbolic link", ErrOutputUnavailable, output)
		}
		if !info.Mode().IsRegular() {
			return "", "", fmt.Errorf("%w: %s is not a regular file", ErrOutputUnavailable, output)
		}
		if err := rejectHardlinkToRepository(outputAbs, repoReal, info); err != nil {
			return "", "", err
		}
	} else if !errors.Is(lerr, os.ErrNotExist) {
		return "", "", fmt.Errorf("%w: cannot inspect %s: %v", ErrOutputUnavailable, output, lerr)
	}
	return dirReal, ".download-*", nil
}

// outputMode decides the mode the delivered file is published with: an
// existing destination keeps its permission bits, a new file gets 0644.
func outputMode(output string) os.FileMode {
	if info, err := os.Lstat(output); err == nil && info.Mode().IsRegular() {
		return info.Mode().Perm()
	}
	return 0o644
}

// resolveExisting resolves symlinks in path, tolerating a nonexistent final
// component (which is then appended lexically). All existing components must
// resolve successfully, so symlinked parent directories are followed here and
// caught by the within-repository check.
func resolveExisting(path string) (string, error) {
	if resolved, err := filepath.EvalSymlinks(path); err == nil {
		return filepath.Clean(resolved), nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return "", fmt.Errorf("cannot resolve output path %q: %v", path, err)
	}
	parent := filepath.Dir(path)
	base := filepath.Base(path)
	resolvedParent, err := filepath.EvalSymlinks(parent)
	if err != nil {
		return "", fmt.Errorf("cannot resolve output directory %q: %v", parent, err)
	}
	return filepath.Join(resolvedParent, base), nil
}

// withinPath reports whether target is path itself or lies beneath base. Both
// arguments should be cleaned lexical paths; comparisons are component-wise so
// "/repo-evil" is not treated as lying beneath "/repo".
func withinPath(target, base string) bool {
	rel, err := filepath.Rel(base, target)
	if err != nil {
		return false
	}
	return rel == "." || rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

// rejectHardlinkToRepository refuses an existing outside destination that
// shares an inode with any repository file that Get must never modify: the
// index, the lock, snapshot records, and content objects. The repository
// directory itself is not a deliverable file and is already excluded by the
// within-repository check.
func rejectHardlinkToRepository(output, repoReal string) error {
	outStat, err := os.Stat(output)
	if err != nil {
		return fmt.Errorf("%w: cannot inspect %s: %v", ErrOutputUnavailable, output, err)
	}
	outDev, outIno := fileIdentity(outStat)
	matches := func(repoFile string) bool {
		info, err := os.Stat(repoFile)
		if err != nil {
			return false
		}
		dev, ino := fileIdentity(info)
		return dev == outDev && ino == outIno
	}
	guarded := []string{
		filepath.Join(repoReal, "index.json"),
		filepath.Join(repoReal, ".lock"),
	}
	for _, guardedFile := range guarded {
		if matches(guardedFile) {
			return fmt.Errorf("%w: %s is a hard link to the repository file %s", ErrOutputUnavailable, output, guardedFile)
		}
	}
	for _, sub := range []string{"objects", "snapshots"} {
		dir := filepath.Join(repoReal, sub)
		err := filepath.WalkDir(dir, func(path string, d os.DirEntry, walkErr error) error {
			if walkErr != nil {
				if errors.Is(walkErr, os.ErrNotExist) {
					return nil
				}
				return walkErr
			}
			if d.IsDir() {
				return nil
			}
			info, err := d.Info()
			if err != nil {
				return err
			}
			dev, ino := fileIdentity(info)
			if dev == outDev && ino == outIno {
				return errHardlinkGuard{path: path}
			}
			return nil
		})
		var guard errHardlinkGuard
		if errors.As(err, &guard) {
			return fmt.Errorf("%w: %s is a hard link to the repository file %s", ErrOutputUnavailable, output, guard.path)
		}
		if err != nil {
			return fmt.Errorf("%w: cannot inspect repository while checking %s: %v", ErrOutputUnavailable, output, err)
		}
	}
	return nil
}

// errHardlinkGuard stops the repository walk as soon as the shared inode is
// found; it carries the matching repository path for the error message.
type errHardlinkGuard struct{ path string }

func (e errHardlinkGuard) Error() string { return "hard link to " + e.path }

func fileIdentity(info os.FileInfo) (dev, ino uint64) {
	if stat, ok := info.Sys().(*syscall.Stat_t); ok {
		return stat.Dev, stat.Ino
	}
	return 0, 0
}

